-- plano do cursor em memoria:
SELECT * FROM TABLE(DBMS_XPLAN.DISPLAY_CURSOR('&sql_id', NULL,
                    'ALLSTATS LAST +PEEKED_BINDS +NOTE'));

-- plano historico (para comparar com o de ontem):
SELECT * FROM TABLE(DBMS_XPLAN.DISPLAY_AWR('&sql_id', &phv, NULL, 'ADVANCED'));

-- carrega o plano BOM (phv conhecido) do cursor cache para a baseline:
DECLARE n NUMBER;
BEGIN
  n := DBMS_SPM.LOAD_PLANS_FROM_CURSOR_CACHE(
         sql_id => '<sql_id>', plan_hash_value => <phv_bom>);
  DBMS_OUTPUT.PUT_LINE('planos carregados: ' || n);
END;
